/bin/bash -lc "python3 - <<'PY'
from PIL import Image
import numpy as np,cv2
im=np.array(Image.open('first_frame.png'))
# 2x2 dominant maps in x40..220 y0..144 brightness charset. axis every 10 chars =20px
for mode in ['lum','sat','red']:
 print('\\n',mode,' x40..220 step2')
 for y in range(0,144,2):
  s=''
  for x in range(40,220,2):
   p=im[y:y+2,x:x+2].mean((0,1));r,g,b=p
   if mode=='lum': v=p.mean(); chars='@%#*+=-:. '; j=min(9,int(v/25.6))
   elif mode=='sat': v=max(p)-min(p);chars=' .:-=+*#%@';j=min(9,int(v/12))
   else: v=r-(g+b)/2; chars=' .:-=+*#%@';j=min(9,max(0,int((v+5)/8)))
   s+=chars[j]
  print(f'{y:03} {s}')
PY"
